mapper.select:
SELECT cm.* FROM consultation_messages cm
INNER JOIN (
    SELECT counselor_id, MAX(sent_time) as max_time
    FROM consultation_messages
    WHERE user_id = #{userId}
    GROUP BY counselor_id
) latest ON cm.counselor_id = latest.counselor_id AND cm.sent_time = latest.max_time
WHERE cm.user_id = #{userId}
ORDER BY cm.sent_time DESC

SELECT cm.* FROM consultation_messages cm
INNER JOIN (
    SELECT user_id, MAX(sent_time) as max_time
    FROM consultation_messages
    WHERE counselor_id = #{counselorId}
    GROUP BY user_id
) latest ON cm.user_id = latest.user_id AND cm.sent_time = latest.max_time
WHERE cm.counselor_id = #{counselorId}
ORDER BY cm.sent_time DESC
